def lfu_cache(maxsize=128, typed=False):
    def decorator(func):
        cache = {}
        usage = {}
        def wrapper(*args, **kwargs):
            if typed:
                key = (tuple((type(a), a) for a in args),
                       tuple((k, type(v), v) for k, v in sorted(kwargs.items())))
            else:
                key = (args, tuple(sorted(kwargs.items())))
            if key in cache:
                usage[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = 1
            if len(cache) > maxsize:
                # find key with min usage
                min_count = min(usage.values())
                # find first key with min_count
                for k in list(usage):
                    if usage[k] == min_count:
                        del cache[k]
                        del usage[k]
