from typing import List, Union

def list_of_file_names(settings_dirs: List[str], spec_option: Union[str, None] = None) -> List[str]:
    """
    Return a sorted list of file names found in the directories specified by `settings_dirs`.
    If `spec_option` is provided, it is used to filter the files:
        - If it starts with a dot (e.g., ".txt") it is treated as a file extension.
        - Otherwise it is treated as a regular expression pattern matched against the file name.
    Non-existent directories are ignored.
    """
    matched_files: List[str] = []

    # Determine filter type
    if spec_option is None:
        def matches(name: str) -> bool:
            return True
    elif isinstance(spec_option, str) and spec_option.startswith('.'):
        ext = spec_option.lower()
        def matches(name: str) -> bool:
            return name.lower().endswith(ext)
    else:
        pattern = re.compile(spec_option)
        def matches(name: str) -> bool:
            return bool(pattern.search(name))

    for dir_path in settings_dirs:
        if not os.path.isdir(dir_path):
            continue
        try:
            for entry in os.listdir(dir_path):
                full_path = os.path.join(dir_path, entry)
                if os.path.isfile(full_path) and matches(entry):
                    matched_files.append(full_path)
        except OSError:
            continue

    return sorted(matched_files)

